const inputData = $input.first().json;

function safeString(value) {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) {
    return value.map(v => safeString(v)).filter(Boolean).join(', ');
  }
  if (typeof value === 'object') {
    if (value.email) return safeString(value.email);
    if (value.address) return safeString(value.address);
    if (value.value) return safeString(value.value);
    if (value.name && value.email) return `${value.name} <${value.email}>`;
    try { return JSON.stringify(value); } catch (e) { return ''; }
  }
  return String(value);
}

function getHeader(name) {
  const headers = inputData.payload?.headers || inputData.headers || inputData.message?.payload?.headers || [];

  if (Array.isArray(headers)) {
    const found = headers.find(h => h.name && h.name.toLowerCase() === name.toLowerCase());
    return safeString(found?.value || '');
  }

  if (headers && typeof headers === 'object') {
    return safeString(headers[name] || headers[name.toLowerCase()] || '');
  }

  return '';
}

function decodeBase64Url(data) {
  if (!data) return '';
  try {
    const base64 = String(data).replace(/-/g, '+').replace(/_/g, '/');
    return Buffer.from(base64, 'base64').toString('utf8');
  } catch (error) {
    return '';
  }
}

function stripHtml(html) {
  return safeString(html)
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractBody(payload) {
  if (!payload) return safeString(inputData.text || inputData.body || inputData.snippet || '');

  if (payload.body?.data) {
    const decoded = decodeBase64Url(payload.body.data);
    return payload.mimeType === 'text/html' ? stripHtml(decoded) : decoded;
  }

  if (Array.isArray(payload.parts)) {
    let plainText = '';
    let htmlText = '';

    for (const part of payload.parts) {
      if (part.mimeType === 'text/plain' && part.body?.data) {
        plainText += decodeBase64Url(part.body.data) + '\n';
      }

      if (part.mimeType === 'text/html' && part.body?.data) {
        htmlText += stripHtml(decodeBase64Url(part.body.data)) + '\n';
      }

      if (Array.isArray(part.parts)) {
        const nested = extractBody(part);
        if (nested) plainText += nested + '\n';
      }
    }

    return plainText.trim() || htmlText.trim() || safeString(inputData.snippet || '');
  }

  return safeString(inputData.snippet || '');
}

function extractEmailAddress(value) {
  const text = safeString(value);
  const angleMatch = text.match(/<([^>]+)>/);
  if (angleMatch) return angleMatch[1].trim();
  const emailMatch = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return emailMatch ? emailMatch[0].trim() : text;
}

const subjectText = safeString(inputData.subject || getHeader('Subject'));
const fromText = safeString(inputData.from || getHeader('From'));
const toText = safeString(inputData.to || getHeader('To'));
const dateText = safeString(inputData.date || getHeader('Date'));
const emailText = safeString(extractBody(inputData.payload) || inputData.text || inputData.body || inputData.snippet || '');
const messageId = safeString(inputData.id || inputData.messageId || inputData.message_id || '');
const combinedForSource = `${toText} ${fromText}`.toLowerCase();

return [
  {
    json: {
      messageId,
      threadId: safeString(inputData.threadId || ''),
      subject: subjectText,
      from: fromText,
      to: toText,
      replyToEmail: extractEmailAddress(fromText),
      date: dateText,
      snippet: safeString(inputData.snippet || ''),
      text: emailText.slice(0, 12000),
      body: emailText.slice(0, 12000),
      accountSource: combinedForSource.includes('info@lovemeer.de')
        ? 'info@lovemeer.de'
        : 'sbbinfo90@gmail.com',
      gmailLink: messageId ? `https://mail.google.com/mail/u/0/#inbox/${messageId}` : ''
    }
  }
];

