const email = $('Code - Extract Email Fields').first().json;
const raw = $json.choices?.[0]?.message?.content || '{}';
let ai;
try {
  ai = JSON.parse(raw);
} catch (e) {
  ai = {
    category: 'NEEDS_REVIEW',
    confidence: 0.0,
    reason: 'AI returned invalid JSON, requires manual review.',
    summary: email.snippet || email.subject,
    suggested_action: 'Review manually.',
    draft_reply_needed: false,
    draft_reply: ''
  };
}

const allowed = ['IMPORTANT', 'BUSINESS_LEAD', 'NEEDS_REVIEW', 'DELETE_CANDIDATE'];
if (!allowed.includes(ai.category)) ai.category = 'NEEDS_REVIEW';

const dangerWords = /collaboration|invoice|payment|contract|offer|supplier|manufacturer|restaurant|event|customer|order|visa|job|university|siteground|domain|tax|bank|legal|medical|government|amt|finanzamt|rechnung/i;
if (ai.category === 'DELETE_CANDIDATE' && dangerWords.test(`${email.subject} ${email.from} ${email.to} ${email.text} ${email.body}`)) {
  ai.category = 'NEEDS_REVIEW';
  ai.reason = `Safety override: original AI decision was delete, but sensitive/business keywords were detected. ${ai.reason || ''}`;
}

return [{
  json: {
    ...email,
    category: ai.category,
    confidence: Number(ai.confidence || 0),
    reason: ai.reason || '',
    summary: ai.summary || '',
    suggestedAction: ai.suggested_action || '',
    draftReplyNeeded: !!ai.draft_reply_needed,
    draftReply: ai.draft_reply || '',
    draftSubject: email.subject?.toLowerCase().startsWith('re:') ? email.subject : `Re: ${email.subject}`
  }
}];
